const wc = $('When Called').first().json;
const task = wc.current_task || {};
const text = (wc.triggering_comment_text || '').trim();
const prompt =
  'Na podstawie zadania i wiadomości użytkownika, wyodrębnij do 3 fraz do wyszukiwania w ClickUp.

' +
  '## Zadanie
' + (task.name || '') + '
' + (task.description || '').slice(0, 800) + '

' +
  '## Wiadomość użytkownika
' + text + '

' +
  'Zwróć TYLKO JSON (bez dodatkowego tekstu):
' +
  '{"queries": ["fraza 1", "fraza 2"], "reason": "krótki powód"}
' +
  'Jeśli brak zewnętrznych odniesień: {"queries": [], "reason": "brak"}';
return [{ json: { search_prompt: prompt } }];

const completion = ($('Extract Queries').first().json.completion || '').trim();
let queries = [];
try {
  const match = completion.match(/\{[\s\S]*\}/);
  if (match) {
    const p = JSON.parse(match[0]);
    queries = (Array.isArray(p.queries) ? p.queries : [])
      .filter(q => typeof q === 'string' && q.trim())
      .slice(0, 3);
  }
} catch(e) {}
return [{ json: { queries } }];

const items = $input.all();
const seen = new Set();
const candidates = [];
for (const item of items) {
  for (const t of (item.json.tasks || [])) {
    if (!t.id || seen.has(t.id)) continue;
    seen.add(t.id);
    const spaceId = String((t.space && t.space.id) || '');
    candidates.push({ id: t.id, name: t.name || '', space_id: spaceId });
  }
}
const space_ids = [...new Set(candidates.map(c => c.space_id).filter(Boolean))];
return [{ json: { candidates, space_ids } }];

const membershipItems = $input.all();
const expandedItems = $('Expand Spaces').all();
const callerUserId = String($('When Called').first().json.caller_user_id || '');
const candidates = $('Merge Results').first().json.candidates || [];

const accessibleSpaces = new Set();
const blockedSpaces = new Set();

for (let i = 0; i < membershipItems.length; i++) {
  const spaceId = (expandedItems[i] && expandedItems[i].json.space_id) || '';
  const members = membershipItems[i].json.members || [];
  const isMember = members.some(m => {
    const uid = String((m.user && m.user.id) !== undefined ? (m.user && m.user.id) : (m.id || ''));
    return uid === callerUserId;
  });
  if (spaceId) { if (isMember) accessibleSpaces.add(spaceId); else blockedSpaces.add(spaceId); }
}

const accessible = candidates.filter(c => accessibleSpaces.has(c.space_id));
const filtered_out = candidates.filter(c => blockedSpaces.has(c.space_id)).length;

return [{ json: { accessible: accessible.slice(0, 3), filtered_out } }];

// Task comments — always attempt
let task_comments = [];
try {
  const r = $('Fetch Task Comments').first().json;
  task_comments = (r.comments || []).slice(0, 30).map(c => ({
    id: c.id,
    author: (c.user && (c.user.username || c.user.email)) || '',
    text: (c.comment_text ||
      (c.comment || []).map(op => (op.text || '')).join('')
    ).slice(0, 600),
    date: c.date
  }));
} catch(e) {}

// Artifact context — only if artifact loop ran
let additional_context = '';
let sources_used = [];
let sources_filtered_out = 0;

try { sources_filtered_out = $('Layer B Filter').first().json.filtered_out || 0; } catch(e) {}

try {
  const readItems = $('Read Task').all();
  const parts = [];
  for (const item of readItems) {
    const t = item.json || {};
    if (!t.id) continue;
    parts.push('### ' + (t.name || t.id));
    if (t.description) parts.push(t.description.slice(0, 1200));
    sources_used.push('task/' + t.id);
  }
  additional_context = parts.join('\n\n');
} catch(e) {}

return [{ json: { task_comments, additional_context, sources_used, sources_filtered_out } }];
